-- Additive staging upgrade. Historical orders retain their frozen commercial terms.
BEGIN;
ALTER TABLE public.program_commerce ALTER COLUMN commission_bps SET DEFAULT 1000;
UPDATE public.program_commerce SET commission_bps=1000,enabled=false,terms_version=NULL,approved_by=NULL,approved_at=NULL WHERE singleton;
ALTER FUNCTION public.approve_program_terms(uuid,boolean,integer,text) RENAME TO approve_program_terms_v58;
CREATE FUNCTION public.approve_program_terms(p_owner uuid,p_enabled boolean,p_bps integer,p_terms text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF p_bps IS DISTINCT FROM 1000 THEN RAISE EXCEPTION 'Hosted programs require the approved 90/10 split';END IF;PERFORM approve_program_terms_v58(p_owner,p_enabled,p_bps,p_terms);END $$;
-- Reject new orders with obsolete terms; never rewrite settled/pending purchases.
CREATE FUNCTION public.guard_program_commission() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NEW.commission_bps<>1000 THEN RAISE EXCEPTION 'New hosted sales require 90/10 commercial terms';END IF;RETURN NEW;END $$;
CREATE TRIGGER program_commission_guard BEFORE INSERT ON public.program_orders FOR EACH ROW EXECUTE FUNCTION public.guard_program_commission();
CREATE FUNCTION public.creator_live_video_count(p_trainer uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT count(*)::integer FROM trainer_videos v WHERE v.user_id=p_trainer AND v.review_status='approved' AND v.category !~* 'youth|homeschool|nutrition' AND (v.access_scope='public' OR EXISTS(SELECT 1 FROM creator_video_access a WHERE a.video_id=v.id AND a.trainer_id=p_trainer)) $$;
REVOKE ALL ON FUNCTION public.creator_live_video_count(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.creator_live_video_count(uuid) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.trainer_is_eligible(p_user_id uuid,p_live boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT account_can_act(p_user_id) AND EXISTS(SELECT 1 FROM profiles WHERE id=p_user_id AND role='trainer')
 AND EXISTS(SELECT 1 FROM certifications WHERE user_id=p_user_id AND status='verified' AND verified_at IS NOT NULL AND verified_by IS NOT NULL AND verified_by<>user_id AND valid_iso_date(expires) AND expires>=to_char(now() AT TIME ZONE 'America/Chicago','YYYY-MM-DD') AND name ~* '\m(CPR|cardiopulmonary resuscitation)\M')
 AND EXISTS(SELECT 1 FROM certifications WHERE user_id=p_user_id AND status='verified' AND verified_at IS NOT NULL AND verified_by IS NOT NULL AND verified_by<>user_id AND valid_iso_date(expires) AND expires>=to_char(now() AT TIME ZONE 'America/Chicago','YYYY-MM-DD') AND name ~* '\m(AED|automated external defibrillator)\M')
 AND NOT EXISTS(SELECT 1 FROM trainer_credential_requirements r WHERE r.trainer_id=p_user_id AND NOT EXISTS(SELECT 1 FROM certifications c WHERE c.user_id=p_user_id AND lower(c.name)=lower(r.credential_name) AND c.status='verified' AND c.verified_at IS NOT NULL AND c.verified_by IS NOT NULL AND c.verified_by<>c.user_id AND valid_iso_date(c.expires) AND c.expires>=to_char(now() AT TIME ZONE 'America/Chicago','YYYY-MM-DD')))
 AND (NOT p_live OR creator_live_video_count(p_user_id)>=5)
$$;
CREATE OR REPLACE FUNCTION public.check_trainer_live_eligibility() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.trainer_id<>OLD.trainer_id THEN RAISE EXCEPTION 'Cannot reassign a class';END IF;IF NOT trainer_is_eligible(NEW.trainer_id,true) OR NOT creator_can_sell(NEW.trainer_id) THEN RAISE EXCEPTION 'Current credentials, five approved videos and payout eligibility required';END IF;IF NEW.starts_at<now() AND (TG_OP='INSERT' OR NEW.starts_at IS DISTINCT FROM OLD.starts_at) THEN RAISE EXCEPTION 'Cannot schedule in the past';END IF;RETURN NEW;END $$;
ALTER TABLE public.live_sessions ADD COLUMN session_type text NOT NULL DEFAULT 'scheduled' CHECK(session_type IN ('scheduled','subscriber'));
CREATE TABLE public.subscriber_live_access(session_id uuid NOT NULL REFERENCES public.live_sessions(id),user_id uuid NOT NULL REFERENCES auth.users(id),reserved_at timestamptz NOT NULL DEFAULT now(),attended_at timestamptz,paid_rebooked_at timestamptz,PRIMARY KEY(session_id,user_id));
ALTER TABLE public.subscriber_live_access ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.subscriber_live_access FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.subscriber_live_access TO service_role;
GRANT SELECT ON public.subscriber_live_access TO authenticated;
CREATE POLICY own_subscriber_attendance ON public.subscriber_live_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM live_sessions WHERE id=session_id AND trainer_id=auth.uid()));
CREATE FUNCTION public.live_subscription_deadline(p_user uuid,p_session uuid) RETURNS timestamptz LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT least(max(r.period_end),s.starts_at+(s.minutes+15)*interval '1 minute') FROM live_sessions s JOIN creator_receipts r ON r.trainer_id=s.trainer_id AND r.user_id=p_user WHERE s.id=p_session AND s.status IN ('scheduled','live') AND s.trainer_id<>p_user AND trainer_is_eligible(s.trainer_id,true) AND creator_has_access(p_user,s.trainer_id) AND r.fulfillable AND NOT r.refund_pending AND r.refunded_cents=0 AND r.period_start<=now() AND r.period_end>now() AND NOT EXISTS(SELECT 1 FROM creator_disputes d WHERE d.order_id=r.id AND d.status IN ('open','lost')) GROUP BY s.starts_at,s.minutes $$;
ALTER FUNCTION public.reserve_live_class(uuid,uuid) RENAME TO reserve_live_class_v53;
CREATE FUNCTION public.reserve_live_class(p_user_id uuid,p_session_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE s live_sessions%ROWTYPE;BEGIN SELECT * INTO s FROM live_sessions WHERE id=p_session_id FOR UPDATE;IF live_subscription_deadline(p_user_id,p_session_id)>now() AND s.starts_at+s.minutes*interval '1 minute'>now() THEN INSERT INTO subscriber_live_access(session_id,user_id) VALUES(p_session_id,p_user_id) ON CONFLICT DO NOTHING;RETURN;END IF;IF s.session_type='subscriber' THEN RAISE EXCEPTION 'Active subscription to this trainer required';END IF;PERFORM reserve_live_class_v53(p_user_id,p_session_id);UPDATE subscriber_live_access SET paid_rebooked_at=now() WHERE session_id=p_session_id AND user_id=p_user_id;END $$;
ALTER FUNCTION public.consume_attended_live_token(uuid,uuid) RENAME TO consume_attended_live_token_v53;
CREATE FUNCTION public.consume_attended_live_token(p_user_id uuid,p_session_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE s live_sessions%ROWTYPE;BEGIN SELECT * INTO s FROM live_sessions WHERE id=p_session_id FOR UPDATE;IF live_subscription_deadline(p_user_id,p_session_id)>now() AND s.starts_at<=now()+interval '10 minutes' AND s.starts_at+s.minutes*interval '1 minute'>now() THEN INSERT INTO subscriber_live_access(session_id,user_id,attended_at) VALUES(p_session_id,p_user_id,now()) ON CONFLICT(session_id,user_id) DO UPDATE SET attended_at=coalesce(subscriber_live_access.attended_at,now());RETURN;END IF;IF s.session_type='subscriber' OR EXISTS(SELECT 1 FROM subscriber_live_access WHERE session_id=p_session_id AND user_id=p_user_id AND paid_rebooked_at IS NULL) THEN RAISE EXCEPTION 'Subscription expired; rebook before paid attendance';END IF;PERFORM consume_attended_live_token_v53(p_user_id,p_session_id);END $$;
CREATE FUNCTION public.start_subscriber_live(p_title text,p_minutes integer DEFAULT 45,p_category text DEFAULT 'Strength',p_level text DEFAULT 'All levels',p_tags text[] DEFAULT '{}',p_description text DEFAULT '',p_recording boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE result uuid;BEGIN IF NOT trainer_is_eligible(auth.uid(),true) OR NOT creator_can_sell(auth.uid()) OR length(trim(p_title)) NOT BETWEEN 1 AND 160 OR p_minutes NOT BETWEEN 5 AND 180 OR p_category NOT IN ('Strength','Cardio','HIIT','Core','Yoga','Pilates','Mobility') OR p_level NOT IN ('Beginner','Intermediate','Advanced','All levels','Postpartum') OR NOT valid_discovery_tags(p_tags) OR length(p_description)>3000 OR p_recording IS NULL THEN RAISE EXCEPTION 'Live eligibility and valid session details required';END IF;PERFORM pg_advisory_xact_lock(hashtext('spontaneous:'||auth.uid()));IF EXISTS(SELECT 1 FROM live_sessions WHERE trainer_id=auth.uid() AND status IN ('scheduled','live') AND starts_at<=now() AND starts_at+(minutes+15)*interval '1 minute'>now()) THEN RAISE EXCEPTION 'End your current session first';END IF;INSERT INTO live_sessions(trainer_id,trainer_name,title,starts_at,minutes,session_type,category,level,discovery_tags,description,recording_enabled) VALUES(auth.uid(),(SELECT name FROM profiles WHERE id=auth.uid()),trim(p_title),now(),p_minutes,'subscriber',p_category,p_level,p_tags,p_description||CASE WHEN p_recording THEN E'\nRecording enabled: footage remains private pending review.' ELSE '' END,p_recording) RETURNING id INTO result;RETURN result;END $$;
CREATE FUNCTION public.announce_subscriber_live() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE u uuid;BEGIN IF NEW.session_type='subscriber' AND NEW.status='live' AND OLD.status<>'live' THEN FOR u IN SELECT DISTINCT r.user_id FROM creator_receipts r JOIN notification_preferences n ON n.user_id=r.user_id AND n.subscriber_lives WHERE r.trainer_id=NEW.trainer_id AND creator_has_access(r.user_id,r.trainer_id) LOOP PERFORM creator_notify(u,'subscriber-live:'||NEW.id,'Your trainer is live for subscribers.','/live');END LOOP;END IF;RETURN NEW;END $$;
CREATE TRIGGER subscriber_live_notice AFTER UPDATE OF status ON public.live_sessions FOR EACH ROW EXECUTE FUNCTION public.announce_subscriber_live();
REVOKE ALL ON FUNCTION public.approve_program_terms_v58(uuid,boolean,integer,text),public.approve_program_terms(uuid,boolean,integer,text),public.guard_program_commission(),public.trainer_is_eligible(uuid,boolean),public.reserve_live_class_v53(uuid,uuid),public.reserve_live_class(uuid,uuid),public.consume_attended_live_token_v53(uuid,uuid),public.consume_attended_live_token(uuid,uuid),public.live_subscription_deadline(uuid,uuid),public.start_subscriber_live(text,integer,text,text,text[],text,boolean),public.announce_subscriber_live() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.approve_program_terms(uuid,boolean,integer,text),public.reserve_live_class(uuid,uuid),public.consume_attended_live_token(uuid,uuid),public.live_subscription_deadline(uuid,uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.trainer_is_eligible(uuid,boolean) TO anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.start_subscriber_live(text,integer,text,text,text[],text,boolean) TO authenticated;
DO $$ DECLARE columns text;BEGIN SELECT string_agg(CASE WHEN attname='discovery_focus_tags' THEN 'public.discovery_focus(l.discovery_tags,l.category||'' ''||l.level) AS discovery_focus_tags' ELSE format('l.%I',attname) END,',' ORDER BY attnum) INTO columns FROM pg_attribute WHERE attrelid='public.discoverable_lives'::regclass AND attnum>0 AND NOT attisdropped;EXECUTE 'CREATE OR REPLACE VIEW public.discoverable_lives WITH(security_barrier=true) AS SELECT '||columns||',l.session_type FROM public.live_sessions l WHERE l.status IN (''scheduled'',''live'') AND public.trainer_is_eligible(l.trainer_id,true) AND l.category !~* ''youth|homeschool|nutrition''';END $$;
CREATE FUNCTION public.guard_creator_live_state() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.session_type IS DISTINCT FROM OLD.session_type THEN RAISE EXCEPTION 'Live access type is immutable; cancel and create a new class';END IF;IF current_setting('role',true)='authenticated' AND NOT has_role(auth.uid(),'admin') AND ((TG_OP='INSERT' AND NEW.status<>'scheduled') OR (TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status)) THEN RAISE EXCEPTION 'Use secure live controls; only verified provider attendance starts broadcasting';END IF;RETURN NEW;END $$;
CREATE TRIGGER creator_live_state_guard BEFORE INSERT OR UPDATE ON public.live_sessions FOR EACH ROW EXECUTE FUNCTION public.guard_creator_live_state();
REVOKE ALL ON FUNCTION public.guard_creator_live_state() FROM PUBLIC,anon,authenticated;
COMMIT;
